\set ON_ERROR_STOP on
-- Disposable fixture ONLY. Never use a production DSN.
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role NOLOGIN; END IF;
END $$;
CREATE SCHEMA extensions;
CREATE EXTENSION pgcrypto WITH SCHEMA extensions;
CREATE TABLE stores(id bigint PRIMARY KEY,is_active boolean,onboarding_status text);
CREATE TABLE employees(id bigint PRIMARY KEY,name text,employee_no int,store_id bigint,is_active boolean,pin_bcrypt text);
CREATE TABLE store_settings(id bigint,open_minute int,close_minute int);
CREATE TABLE attendance_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id bigint,event_type text,event_at timestamp,server_received_at timestamp,device_id text,substitute_for_employee_id bigint);
CREATE TABLE event_corrections(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id bigint,event_id bigint,action text,new_event_at timestamp,new_event_type text,reason text,created_by text,created_at timestamptz DEFAULT now());
CREATE TABLE correction_requests(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id bigint,event_id bigint,kind text,requested_at timestamp,requested_type text,note text,status text DEFAULT 'PENDING',created_at timestamptz DEFAULT now());
CREATE TABLE substitution_requests(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,requester_employee_id bigint,substitute_employee_id bigint,work_start timestamp,work_end timestamp,note text,status text DEFAULT 'REQUESTED',requested_at timestamptz DEFAULT now(),accepted_at timestamptz,resolved_at timestamptz,actual_minutes int);
CREATE FUNCTION attendance_correction_effective_utc(t timestamp,b text,c timestamptz) RETURNS timestamp LANGUAGE sql AS $$ SELECT CASE WHEN b LIKE 'system:%' THEN t ELSE t-interval '9 hours' END $$;
CREATE FUNCTION attendance_correction_effective_kst(t timestamp,b text,c timestamptz) RETURNS timestamp LANGUAGE sql AS $$ SELECT CASE WHEN b LIKE 'system:%' THEN t+interval '9 hours' ELSE t END $$;
CREATE FUNCTION substitution_is_working(e bigint) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce((SELECT event_type='IN' FROM attendance_events WHERE employee_id=e ORDER BY event_at DESC,id DESC LIMIT 1),false) $$;
CREATE FUNCTION substitution_schedule_conflict(e bigint,s timestamp,f timestamp) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION substitution_enforce_due() RETURNS void LANGUAGE sql AS $$ SELECT $$;
CREATE FUNCTION substitution_refresh_one(r bigint) RETURNS void LANGUAGE sql AS $$ SELECT $$;
CREATE SCHEMA pos_private;
CREATE TABLE pos_private.unlock_attempts(store_id bigint,employee_no int,success boolean,attempted_at timestamptz DEFAULT clock_timestamp());
CREATE TABLE pos_private.kiosk_sessions(store_id bigint,employee_id bigint,token_digest bytea,expires_at timestamptz);
CREATE TABLE inventory_items(id bigint PRIMARY KEY,name text,unit text,is_active boolean,is_demo boolean);
CREATE TABLE inventory_movements(item_id bigint,store_id bigint,quantity numeric,is_demo boolean);
CREATE TABLE store_staff_stocktake_proposals(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,store_id bigint,employee_id bigint,lines jsonb,note text,counted_on date DEFAULT (now() AT TIME ZONE 'Asia/Seoul')::date);
CREATE TABLE recipe_source_variants(menu_name text,category text,thumbnail_url text);
CREATE TABLE hq_products(id bigint,recipe_version_id bigint,product_key text,name text,status text);
CREATE TABLE recipe_versions(id bigint,thumbnail_url text);
CREATE TABLE store_recipe_overrides(store_id bigint,menu_key text,menu_name text,category text,thumbnail_url text,instructions jsonb,components jsonb);
CREATE FUNCTION recipe_thumbnail_for_source(t text) RETURNS text LANGUAGE sql AS $$ SELECT ''::text $$;
CREATE FUNCTION source_recipe_instructions(t text) RETURNS jsonb LANGUAGE sql AS $$ SELECT '[]'::jsonb $$;
CREATE FUNCTION source_recipe_components(t text) RETURNS jsonb LANGUAGE sql AS $$ SELECT '[]'::jsonb $$;
INSERT INTO stores VALUES (710001,true,'READY'),(710002,true,'READY'),(710003,false,'STAGED');
INSERT INTO employees SELECT n,'Synthetic employee '||n,n-710000,CASE WHEN n=710003 THEN 710003 WHEN n=710004 THEN 710002 ELSE 710001 END,true,extensions.crypt('1234',extensions.gen_salt('bf',4)) FROM generate_series(710001,710040) n;
INSERT INTO store_settings VALUES(710001,0,2880),(710002,0,2880);
INSERT INTO inventory_items VALUES(710001,'Synthetic beans','g',true,false);
INSERT INTO recipe_source_variants VALUES('Synthetic recipe','coffee','');
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
